using Microsoft.ML.Data;

namespace TicketClassifier.Models;

/// <summary>
/// Raw ticket fed into the ML pipeline.
/// </summary>
public sealed class TicketInput
{
    [LoadColumn(0)] public string Subject { get; set; } = "";
    [LoadColumn(1)] public string Description { get; set; } = "";
    [LoadColumn(2)] public float Priority { get; set; }
    [LoadColumn(3)] public string Category { get; set; } = "";
}

/// <summary>
/// ML.NET prediction output.
/// </summary>
public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = "";

    public float[] Score { get; set; } = [];
}

/// <summary>
/// Request DTO for the prediction endpoint.
/// </summary>
public sealed class PredictRequest
{
    public string Subject { get; set; } = "";
    public string Description { get; set; } = "";
    public int Priority { get; set; } = 3;
}

/// <summary>
/// Response DTO returned by the prediction endpoint.
/// </summary>
public sealed class PredictResponse
{
    public string PredictedCategory { get; set; } = "";
    public Dictionary<string, float> Scores { get; set; } = new();
}

/// <summary>
/// Evaluation metrics returned by the /api/tickets/metrics endpoint.
/// </summary>
public sealed class MetricsResponse
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketInput, TicketPrediction> _predictionEngine;
    private readonly MetricsResponse _metrics;
    private readonly string[] _labelNames;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        // Load data
        IDataView data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Build pipeline:
        //  1. Map Category string → numeric key (label)
        //  2. Featurize the two text columns
        //  3. Concatenate all features
        //  4. Train with SdcaMaximumEntropy
        //  5. Map predicted key back to string
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        // Train
        _model = pipeline.Fit(data);

        // Evaluate (cross-validation with the small dataset)
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(data, pipeline, numberOfFolds: 3, labelColumnName: "Label");

        _metrics = new MetricsResponse
        {
            MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
            MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
            LogLoss       = cvResults.Average(r => r.Metrics.LogLoss),
            LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction)
        };

        // Cache prediction engine and label order
        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketInput, TicketPrediction>(_model);

        // Extract label names in key-order so we can pair them with Score[]
        VBuffer<ReadOnlyMemory<char>> labelBuffer = default;
        _model.GetOutputSchema(data.Schema)["Score"]
            .GetSlotNames(ref labelBuffer);
        _labelNames = labelBuffer.DenseValues()
            .Select(v => v.ToString()).ToArray();
    }

    public PredictResponse Predict(PredictRequest request)
    {
        var input = new TicketInput
        {
            Subject     = request.Subject,
            Description = request.Description,
            Priority    = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < _labelNames.Length; i++)
            scores[_labelNames[i]] = prediction.Score.Length > i ? prediction.Score[i] : 0f;

        return new PredictResponse
        {
            PredictedCategory = prediction.Category,
            Scores = scores
        };
    }

    public MetricsResponse GetMetrics() => _metrics;
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketController(TicketClassifierService classifier) : ControllerBase
{
    /// <summary>POST api/ticket/predict – classify a support ticket.</summary>
    [HttpPost("predict")]
    public ActionResult<PredictResponse> Predict([FromBody] PredictRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) &&
            string.IsNullOrWhiteSpace(request.Description))
        {
            return BadRequest("Subject or Description is required.");
        }

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(classifier.Predict(request));
    }

    /// <summary>GET api/ticket/metrics – return model evaluation metrics.</summary>
    [HttpGet("metrics")]
    public ActionResult<MetricsResponse> Metrics() => Ok(classifier.GetMetrics());
}

